conditions.value_template:
{% set lv_groups = ['sensor.mean_moisture_lv1', 'sensor.mean_moisture_lv2', 'sensor.mean_moisture_lv3'] %}
{% set lv_sensors = expand(lv_groups) | map(attribute='attributes.entity_id') | sum(start=[]) | unique | list %}
{% set ns = namespace(latest=0) %}
{% for s in expand(lv_sensors) %}
  {% if s.state not in ['unknown', 'unavailable'] %}
    {% set ts = as_timestamp(s.last_updated, 0) %}
    {% if ts > ns.latest %}
      {% set ns.latest = ts %}
    {% endif %}
  {% endif %}
{% endfor %}
{{ (as_timestamp(now()) - ns.latest) >= 86400 }}
